func matchAgency(query string, agencies []agencyReference) (agencyReference, []agencyReference) {
	needle := strings.ToLower(strings.TrimSpace(query))
	var alternates []agencyReference
	for _, agency := range agencies {
		if strings.ToLower(agency.Abbreviation) == needle || strings.ToLower(agency.AgencyName) == needle {
			return agency, nil
		}
	}
	for _, agency := range agencies {
		haystack := strings.ToLower(agency.Abbreviation + " " + agency.AgencyName)
		if strings.Contains(haystack, needle) {
			if len(alternates) < 5 {
				alternates = append(alternates, agency)
			}
		}
	}
	if len(alternates) > 0 {
		return alternates[0], alternates[1:]
	}
	return agencyReference{AgencyName: query}, nil
}

